@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @bind="_content" @bind:event="oninput" rows="15" style="width:100%;"></textarea>

<p>
    @if (_lastSavedAt is not null)
    {
        <span>Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</p>

<button @onclick="SaveNowAsync">Save now</button>
<button @onclick="ClearAsync">Clear</button>

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private string _content = string.Empty;
    private string _savedContent = string.Empty;
    private DateTime? _lastSavedAt;
    private System.Threading.Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var restored = await _interop.LoadAsync();
            if (restored is not null)
            {
                _content = restored;
                _savedContent = restored;
                StateHasChanged();
            }

            _autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private bool HasUnsavedChanges => _content != _savedContent;

    private async Task AutoSaveAsync()
    {
        await SaveAsync();
        StateHasChanged();
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _savedContent = _content;
        _lastSavedAt = DateTime.Now;

        await _interop.SetBeforeUnloadAsync(false);
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = null;

        await _interop.ClearAsync();
        await _interop.SetBeforeUnloadAsync(false);
    }

    [JSInvokable]
    public async Task OnContentChanged()
    {
        await InvokeAsync(() =>
        {
            if (_interop is not null && HasUnsavedChanges)
            {
                _ = _interop.SetBeforeUnloadAsync(true);
            }
        });
    }

    private async Task OnInput()
    {
        if (_interop is not null && HasUnsavedChanges)
        {
            await _interop.SetBeforeUnloadAsync(true);
        }
        else if (_interop is not null)
        {
            await _interop.SetBeforeUnloadAsync(false);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        try
        {
            if (_interop is not null)
            {
                await _interop.SetBeforeUnloadAsync(false);
                await _interop.DisposeAsync();
            }
        }
        catch (JSDisconnectedException) { }
    }
